// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address _distributor) public {
        vm.assume(_distributor != address(0));
        c.setRewardDistributor(_distributor);
        assertTrue(c.rewardDistributor() == _distributor);
    }
}

